style.css:
@-moz-document domain("stackoverflow.com"), domain("superuser.com"), domain("serverfault.com"), domain("askubuntu.com"), domain("mathoverflow.net"), domain("stackexchange.com"), domain("stackapps.com") {
/* StackExchange Dark — one shared frontend ("Stacks" on a light `unified-theme`
     body) across SO, every network Q&A site and the hub; native dark is a logged-in
     preference, so anonymous visitors only see the light site. Literal hex on stable
     Stacks classes. Two token layers:
     - the global :root palette (--black-050 … --black-600, --bc-light, --white):
     never remap it — one token paints both text and surfaces, so flipping one
     inverts unrelated components. Use class-level rules.
     - per-component tokens (--_bl-*, --_av-*, --_se-arrow-bc, --_me-*): no .fc- or
     .bg- utility remap reaches them, so a component coloured only this way must be
     fixed by redefining ITS token, which also preserves the geometry it feeds.
     Palette: base #14181d, elevated #1c2128, elevated-2 #222831, header/footer
     #0d1117, borders #262c33 / #2d333b, ink #e6edf3 / #c4cdd6 / #9198a1, link
     #5fb0e6 hover #9bd4ff, orange #d98b3a, green #3fb950, tag #20303d / #8cc6f0 */

  :root {
    color-scheme: dark;
  }

  /* ---- Base ---- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* The smaller network sites tile a LIGHT `site-background-image.svg` over <body>;
     SO ships none, so killing it globally is safe. */
  html,
  body,
  body.unified-theme {
    background-image: none !important;
  }

  body.unified-theme {
    background-color: #14181d !important;
  }

  /* One `--scrollbar` token paints every custom scrollbar THUMB (20% black,
     invisible on dark). It feeds nothing but `::-webkit-scrollbar-thumb`, so
     flipping it is safe. Declared on `body`, not `:root`. */
  body,
  body.unified-theme {
    --scrollbar: rgba(255, 255, 255, 0.22) !important;
  }

  /* Generic light-surface neutralizers; specific surfaces are re-elevated below. */
  .bg-white,
  .s-page,
  #content,
  .container,
  #mainbar,
  #mainbar-full,
  .snippet-hidden,
  .ws-nowrap.bg-white {
    background-color: transparent !important;
  }

  /* Stacks compiles each `h:` hover utility grouped with its static sibling, so the
     `:hover` arm is TWO simple selectors with !important and out-ranks any one-class
     override here. `[class~="…"]` keeps that weight without escaping the colon. Must
     precede the component sections so their specific hovers win at equal
     specificity. */
  [class~="h:bg-white"]:hover,
  [class~="h:bg-black-050"]:hover,
  [class~="h:bg-black-075"]:hover,
  [class~="h:bg-black-100"]:hover,
  [class~="h:bg-black-150"]:hover,
  [class~="h:bg-black-200"]:hover,
  [class~="h:bg-black-225"]:hover {
    background-color: #222831 !important;
  }

  [class~="h:bg-purple-100"]:hover,
  [class~="h:bg-purple-200"]:hover {
    background-color: #2b2545 !important;
  }

  [class~="h:fc-black-300"]:hover,
  [class~="h:fc-black-350"]:hover,
  [class~="h:fc-black-400"]:hover,
  [class~="h:fc-black-450"]:hover,
  [class~="h:fc-black-500"]:hover,
  [class~="h:fc-black-600"]:hover,
  [class~="h:fc-dark"]:hover,
  [class~="h:fc-medium"]:hover {
    color: #e6edf3 !important;
  }

  [class~="h:fc-blue-500"]:hover,
  [class~="h:fc-blue-600"]:hover {
    color: #9bd4ff !important;
  }

  /* ---- Headings & text ---- */
  /* `h2:not([style*="color"])` spares the hub's /sites grid: each tile's ink is set
     INLINE on the <h2>, and an !important cannot yield to an inline value. */
  h1, h2:not([style*="color"]), h3, h4, h5, h6,
  .fs-headline1, .fs-headline2, .fs-title, .fs-subheading,
  .s-prose h1, .s-prose h2, .s-prose h3, .s-prose h4 {
    color: #e6edf3 !important;
  }

  .fc-black-800, .fc-black-900, .fc-black-700,
  .fc-dark, .fc-medium {
    color: #e6edf3 !important;
  }

  .fc-black-600, .fc-black-500,
  .fc-medium,
  .post-signature .user-action-time,
  .mod-message, .subheader h1 {
    color: #c4cdd6 !important;
  }

  /* SE's muted greys: timestamps, share/edit links, metadata, nav item text. */
  .fc-black-450, .fc-black-400, .fc-black-350,
  .fc-black-300, .fc-black-250, .fc-black-200,
  .fc-light, .s-description, .fs-caption,
  .relativetime, .relativetime-clean,
  .s-user-card--time, .s-link__muted,
  .js-share-link, .js-suggest-edit-post,
  .s-navigation--item, .disabled-link,
  .v-visible-sr, .post-menu .lsep,
  .s-post-summary--stats-item,
  .s-empty-state, .s-empty-state p,
  .s-empty-state .fs-body2,
  .s-prose .fc-light,
  .revision-comment, span.revision-comment {
    color: #9198a1 !important;
  }

  /* `.s-link__muted` reads `--_li-fc: var(--black-400)`, the same token as the
     metadata around it, so it belongs in the muted group. Its rest colour is
     !important, so this hover arm is required. */
  .s-link__muted:hover {
    color: #c4cdd6 !important;
  }

  /* `.fc-black` has NO numeric step: pure #000, a separate utility from the
     `.fc-black-NNN` scale, declared AFTER it as Stacks does, so an element with both
     resolves to the prominent ink. `.iconLogoNew.fc-black` below still wins. */
  .fc-black {
    color: #e6edf3 !important;
  }

  /* The `.fc-purple-*` scale runs dark like the blue one (--purple-500 #393fac is
     1.9:1 on a card). Steps 100-300 are already light enough on dark. */
  .fc-purple-400,
  .fc-purple-500,
  .fc-purple-600,
  .fc-purple-700,
  .fc-purple-800,
  .fc-purple-900 {
    color: #a78bfa !important;
  }

  /* The "Skip to main content" link is clipped to 1px until focused, then expands
     to a full-width bar on SE's white background. */
  .s-topbar--skip-link,
  .s-topbar--skip-link:focus,
  a.s-topbar--skip-link:focus {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* The BLUE scale is as dark as the black one, and `.fc-*` utilities are
     !important in Stacks, so a bare `a { color }` never beats them. */
  .fc-blue-400 {
    color: #5fb0e6 !important;
  }

  .fc-blue-500,
  .fc-blue-600,
  .fc-blue-700,
  .fc-blue-800,
  .fc-blue-900 {
    color: #6fb3e8 !important;
  }

  /* The SELECTED nav pill is SE's theme ORANGE with WHITE text; the muted-grey rule
     above would flatten it. */
  .s-navigation--item.is-selected,
  a.s-navigation--item.is-selected,
  .s-navigation--item.is-selected .s-navigation--item-text {
    color: #ffffff !important;
  }

  /* …but the MUTED variant re-points `--_na-item-selected-bg` to a near-white
     `--black-150`, so the white label above would land on a white pill. Scope by that
     token, not `.is-selected` — the plain `.s-navigation` keeps its orange pill.
     `--_na-item-selected-bg-hover` is deliberately untouched: Stacks sets it to
     `none`, so the pill drops on hover. */
  .s-navigation__muted,
  .s-navigation.s-navigation__muted {
    --_na-item-selected-bg: #2d333b !important;
    --_na-item-selected-fc: #e6edf3 !important;
  }

  /* Hover on an unselected `.s-navigation--item` paints from `--_na-item-bg-hover`,
     a component token no `.bg-*` remap reaches. `:not(.is-selected)` is
     load-bearing: `.is-selected` re-points that same token at the brand orange. */
  .s-navigation--item:not(.is-selected) {
    --_na-item-bg-hover: #21262d !important;
    --_na-item-fc-hover: #e6edf3 !important;
  }

  /* In the top bar the component token is NOT what paints: a separate Stacks rule
     fills from `var(--theme-topbar-item-background-hover, var(--black-200))`, which
     no network site defines. `:not(.is-selected)` spares the open item's pill. */
  .s-topbar .s-navigation .s-navigation--item:not(.is-selected):hover,
  .s-topbar .s-popover .s-navigation .s-navigation--item:not(.is-selected):hover {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  .s-navigation--item:not(.is-selected):hover,
  .s-navigation--item:not(.is-selected):hover .s-navigation--item-text {
    color: #e6edf3 !important;
  }

  /* The user-card display NAME is a real link SE paints blue; the muted metadata
     list above would flatten it. */
  .s-user-card--link,
  a.s-user-card--link,
  .s-user-card--info .s-user-card--link {
    color: #5fb0e6 !important;
  }

  .s-user-card--link:hover,
  a.s-user-card--link:hover {
    color: #9bd4ff !important;
  }

  /* …but a user with no profile is a bare <span class="s-user-card--link"> at the
     body ink: match `.s-user-card--time`, not the accent. */
  span.s-user-card--link,
  .s-user-card--info span.s-user-card--link {
    color: #9198a1 !important;
  }

  /* `.fs-caption` is a SIZE utility, not a colour: SE also puts it on accent text
     and on links, both swallowed by the blanket mute. Two classes beats it. */
  .fc-orange-400,
  .fs-caption.fc-orange-400,
  .fc-orange-400.fs-caption {
    color: #d98b3a !important;
  }

  a.s-link.fs-caption,
  .fs-caption a.s-link {
    color: #5fb0e6 !important;
  }

  /* …and their hover arm: the !important rest colour above out-ranks the
     unimportant generic `a:hover`. */
  a.s-link.fs-caption:hover,
  .fs-caption a.s-link:hover {
    color: #9bd4ff !important;
  }

  /* A `.relativetime` inside an anchor is HALF that link's label, so it must
     inherit the anchor's colour rather than take the blanket mute. */
  a .relativetime,
  a span.relativetime,
  a .relativetime-clean {
    color: inherit !important;
  }

  /* Site-switcher hints and other plain body-size helper text default to SE's
     near-black #3b4045. */
  .ps-relative .fs-body2,
  .site-switcher .fs-body2,
  .modal-content .fs-body2,
  .s-popover .fs-body2,
  .grid--cell > .fs-body2,
  span.flex--item.fs-body2 {
    color: #9198a1 !important;
  }

  /* `.ps-relative` is a layout utility, so the helper-text mute above reaches any
     body-size text in a positioned box. An explicit dark-ink utility marks a
     heading. */
  .ps-relative .fs-body2.fc-black-700,
  .s-popover .fs-body2.fc-black-700,
  .modal-content .fs-body2.fc-black-700,
  .grid--cell > .fs-body2.fc-black-700 {
    color: #e6edf3 !important;
  }

  /* Same on the BLUE end: the mute is 2 classes and the `.fc-blue-*` remap 1, so an
     explicit link-blue utility on body-size text loses. */
  .fs-body2.fc-blue-400,
  .fs-body2.fc-blue-500,
  .fs-body2.fc-blue-600,
  .fs-body2.fc-blue-700 {
    color: #6fb3e8 !important;
  }

  /* Labels, strong metadata, user-card rows: dark #3b4045 by default. */
  .s-label,
  label.s-label,
  .s-user-card--rep,
  .s-user-card--awards,
  .s-prose strong.fc-black-500,
  .post-layout strong,
  .grid--cell strong,
  .fw-bold.fc-black-500 {
    color: #c4cdd6 !important;
  }

  /* ---- Links ---- */
  a, .s-link,
  .comment-copy a, .s-prose a,
  .s-tag.post-tag a, .post-tag {
    color: #5fb0e6;
  }

  /* Question/answer title links default to SE's dark #3b4045. */
  .question-hyperlink,
  .answer-hyperlink,
  a.question-hyperlink,
  .spacer .question-hyperlink,
  .related a, .linked a {
    color: #6fb3e8 !important;
  }

  a:hover, .s-link:hover, .s-prose a:hover,
  .question-hyperlink:hover, .answer-hyperlink:hover {
    color: #9bd4ff;
  }

  /* `.s-link__inherit` is Stacks' explicit opt-OUT of the link colour
     (`--_li-fc: inherit`). Two classes beats our `.s-link` arm; no !important, so the
     places we DO paint (`#sidebar a`, `.fc-blue-400`, the HNQ heading) still win. */
  a.s-link__inherit,
  .s-link.s-link__inherit {
    color: inherit;
  }

  /* VISITED links. The generic accent is unimportant, so SE's `:visited` rules — one
     pseudo-class more specific — win on every opened link. Two arms: some engines
     refuse to repaint an already-visited link from a later author rule, so the FLOOR
     (no `:visited`, !important) guarantees the accent while the violet arm keeps the
     read/unread signal where `:visited` does apply. The `:not()` chain mirrors SE's
     exclusions — tags, badges and buttons keep their own fill. */
  .s-prose a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn),
  .comment-copy a:not(.badge):not(.s-btn) {
    color: #5fb0e6 !important;
  }

  .s-prose a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):hover,
  .comment-copy a:not(.badge):not(.s-btn):hover {
    color: #9bd4ff !important;
  }

  .s-prose a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):visited,
  .comment-copy a:not(.badge):not(.s-btn):visited,
  .s-link:not(.s-btn):not(.post-tag):not(.badge-tag):visited {
    color: #b09ae0 !important;
  }

  .s-prose a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):visited:hover,
  .comment-copy a:not(.badge):not(.s-btn):visited:hover,
  .s-link:not(.s-btn):not(.post-tag):not(.badge-tag):visited:hover {
    color: #d3c4f5 !important;
  }

  /* Same two arms for the Help Center index: its FAQ lists are `.wiki-ph-content`,
     not `.s-prose`, so the floor above never reaches them. */
  .wiki-ph-content a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn) {
    color: #5fb0e6 !important;
  }

  .wiki-ph-content a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):hover {
    color: #9bd4ff !important;
  }

  .wiki-ph-content a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):visited {
    color: #b09ae0 !important;
  }

  .wiki-ph-content a:not(.s-tag):not(.post-tag):not(.badge-tag):not(.badge):not(.s-btn):visited:hover {
    color: #d3c4f5 !important;
  }

  /* Same two arms again for the user-card and user-list anchors, which are BARE
     <a> with no class and so lose to SE's five-`:not()` `:visited` rule. */
  .user-tags a,
  .s-user-card--link a,
  .s-user-card--awards a,
  #users-legend a {
    color: #5fb0e6 !important;
  }

  .user-tags a:hover,
  .s-user-card--link a:hover,
  .s-user-card--awards a:hover,
  #users-legend a:hover {
    color: #9bd4ff !important;
  }

  .user-tags a:visited,
  .s-user-card--link a:visited,
  .s-user-card--awards a:visited,
  #users-legend a:visited {
    color: #b09ae0 !important;
  }

  .user-tags a:visited:hover,
  .s-user-card--link a:visited:hover,
  .s-user-card--awards a:visited:hover,
  #users-legend a:visited:hover {
    color: #d3c4f5 !important;
  }

  /* The RSS feed link: the network home ships its own
     `#feed-link a { color: #777 }`, the only link there that is not the accent. */
  #feed-link a {
    color: #5fb0e6 !important;
  }

  /* Top bar / global navigation */
  .s-topbar,
  .top-bar,
  .js-top-bar {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #262c33 !important;
    box-shadow: 0 1px 0 rgba(0, 0, 0, 0.4) !important;
  }

  .s-topbar .s-topbar--item > .s-btn,
  .s-topbar .-link,
  .topbar-links .links-container .topbar-icon,
  .s-topbar a {
    color: #c4cdd6 !important;
  }

  .s-topbar .s-topbar--item > .s-btn:hover,
  .s-topbar .-link:hover {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* The search-syntax popover hangs off the searchbar, so `.s-topbar a` steals its
     link blue. Scoped to the hint block: a blanket `.s-topbar .s-popover a` would
     repaint the `.s-block-link` rows in the other popovers; `:not(.s-btn)` spares
     the filled CTA. */
  .s-topbar .js-search-hints a:not(.s-btn),
  .s-topbar .js-search-hints a.s-link:not(.s-btn) {
    color: #5fb0e6 !important;
  }

  .s-topbar .js-search-hints a:not(.s-btn):hover {
    color: #9bd4ff !important;
  }

  /* Same trap in the site-switcher pane: its whole-row `.s-block-link` entries are
     deliberately grey, but the pane also carries INLINE links SE paints `--blue-500`
     with no underline. Scoped to the three inline shapes. */
  .siteSwitcher-dialog a.login-link,
  .siteSwitcher-dialog .related-links a,
  .siteSwitcher-dialog .header a.float-right {
    color: #5fb0e6 !important;
  }

  .siteSwitcher-dialog a.login-link:hover,
  .siteSwitcher-dialog .related-links a:hover,
  .siteSwitcher-dialog .header a.float-right:hover {
    color: #9bd4ff !important;
  }

  /* Every topbar dropdown trigger gets `.is-selected` while its dialog is open, and
     SE fills the selected item near-white. */
  .s-topbar .s-topbar--item.is-selected,
  a.s-topbar--item.is-selected,
  .s-topbar--item.is-selected {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* …and the same fill on plain HOVER, from Stacks'
     `var(--theme-topbar-item-background-hover, var(--black-200))` fallback.
     `:not(.s-topbar--item__unset)` is load-bearing and mirrors SE's selector: "Log
     in" / "Sign up" carry `.s-topbar--item` too, and this rule out-specifies our
     `.s-btn__filled:hover` accent. */
  .s-topbar .s-topbar--item:not(.s-topbar--item__unset):hover,
  .s-topbar .s-topbar--item:not(.s-topbar--item__unset):hover .svg-icon {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* The narrow-viewport search trigger (`.js-searchbar-trigger`) is the one topbar
     item that is also a `.s-btn__muted`, so on hover Stacks adds its muted-button
     `--black-300` border on top of the plate above. */
  .s-topbar .s-topbar--item.s-btn__muted:not(.s-topbar--item__unset):hover {
    border-color: #2d333b !important;
  }

  /* The site wordmark is a `.s-topbar--logo` link and takes the same near-white
     fill from its own `--_tb-logo-bg` token. */
  .s-topbar a.s-topbar--logo:hover,
  .s-topbar a.s-topbar--logo.is-selected,
  .s-topbar .s-topbar--logo:hover {
    --_tb-logo-bg: #21262d !important;
    background-color: #21262d !important;
  }

  /* Mobile hamburger: SE marks it `.is-selected` once the drawer is open and paints
     it near-white. Only visible below the `md` breakpoint. */
  .s-topbar--menu-btn,
  .s-topbar .s-topbar--menu-btn {
    color: #c4cdd6 !important;
  }

  .s-topbar--menu-btn:hover,
  .s-topbar--menu-btn.is-selected,
  .s-topbar .s-topbar--menu-btn.is-selected {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* Site-switcher / network dropdown */
  .s-topbar .-logo,
  .s-topbar .-logo .-img {
    filter: none;
  }

  /* The "Meta <site>" child row's L-shaped connector is built from BORDERS on
     `.L-shaped-icon`, kept a light #b9c1c5. */
  .L-shaped-icon,
  .related-site .L-shaped-icon {
    border-color: #3d444d !important;
  }

  /* The auth-page wordmark is an SVG carrying `.fc-black` (pure #000). */
  svg.iconLogoNew,
  svg.iconLogoNewSm,
  svg.iconGlyphNew,
  .iconLogoNew.fc-black,
  .fc-black.iconLogoNew {
    color: #e6edf3 !important;
    fill: #e6edf3 !important;
  }

  /* Non-SO network header logos are <img> dark wordmarks baked for the white site,
     so they take the standard luminance invert (hue-rotate keeps brand hues); SO's is
     an inline SVG, handled above. Sites whose header band is a BRAND colour reset
     this at the end of the file. */
  .site-header--link img,
  a.site-header--link img,
  #hlogo img,
  .-logo img {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* The network-site auth page's per-site wordmark (LogoEmail.png) is neither an
     `.-logo` / `#hlogo` / `.site-header--link` img nor SO's inline SVG, so the rules
     above miss it. Scoped to the auth body; OAuth icons are inline SVGs. */
  body.universal-auth-page a.s-link img {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Stack Apps' default question-thumbnail plates are solid white. The selector
     shape is pinned by two constraints: the slot also holds user uploads, never
     served from the site's own `/Content/Sites/<site>/Img/`, and that directory also
     holds brand rasters that must not invert. Match directory AND `-thumb.png`. */
  img[src*="/Content/Sites/"][src*="-thumb.png"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Below `md` the searchbar is a full-width overlay row Stacks fills from the same
     undefined `var(--theme-topbar-item-background-hover, var(--black-200))` token.
     `.searchbar` is legacy and matches nothing today (the live class is
     `.s-topbar--searchbar`). */
  .s-topbar .searchbar,
  .top-bar .searchbar,
  .s-topbar .s-topbar--searchbar,
  .s-topbar .s-topbar--searchbar.s-topbar--searchbar__open {
    background-color: #0d1117 !important;
  }

  /* Search inputs / all text inputs */
  .s-input,
  .s-textarea,
  input.s-input,
  textarea.s-textarea,
  input[type="text"],
  input[type="search"],
  input[type="email"],
  input[type="password"],
  input[type="url"],
  input[type="number"],
  textarea,
  select,
  select.s-select,
  .s-select select,
  .s-input__search {
    background-color: #222831 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* The "Sorted by" control is a bare unclassed <select> inside a `.s-select`
     wrapper — SE styles the wrapper, not the control. */
  select option {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* The caret is a pair of CSS triangles from `--_se-arrow-bc: <colour>
     transparent`. Keep the two-value form: a flat colour fills the transparent sides
     and turns each triangle into a rectangle. */
  .s-select {
    --_se-arrow-bc: #9198a1 transparent !important;
  }

  .s-input:focus,
  .s-textarea:focus,
  input:focus,
  textarea:focus {
    border-color: #5fb0e6 !important;
    box-shadow: 0 0 0 2px rgba(95, 176, 230, 0.25) !important;
  }

  /* Placeholders: legible muted grey, never the input bg */
  .s-input::placeholder,
  .s-textarea::placeholder,
  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* The top-bar search icon */
  .s-input__icon, .svg-icon.iconSearch {
    color: #8b949e !important;
  }

  /* Stacks renders `.s-checkbox` / `.s-radio-button` as appearance:none controls
     painted solid WHITE. The checked state keeps the accent fill + white glyph. */
  input[type="checkbox"],
  input[type="radio"],
  .s-checkbox,
  .s-radio-button {
    background-color: #222831 !important;
    border-color: #2d333b !important;
  }

  input[type="checkbox"]:checked,
  input[type="radio"]:checked,
  .s-checkbox:checked,
  .s-radio-button:checked {
    background-color: #2f6f9f !important;
    border-color: #3b82b8 !important;
  }

  /* Left navigation sidebar */
  #left-sidebar,
  .left-sidebar,
  .left-sidebar--sticky-container,
  .ps-relative.h100.js-pinned-left-sidebar {
    background-color: transparent !important;
  }

  #left-sidebar .pl16,
  .nav-links .nav-links--link,
  .left-sidebar .nav-links--link {
    color: #c4cdd6 !important;
  }

  /* Nav links sit flush at rest: the link AND its inner `.-link--channel-name` span
     must be transparent, or the elevated-chip rule below boxes every label. */
  .nav-links .nav-links--link,
  .left-sidebar .nav-links--link,
  #left-sidebar .nav-links--link,
  .nav-links--link .-link--channel-name,
  .left-sidebar .nav-links--link .-link--channel-name {
    background-color: transparent !important;
  }

  /* The at-rest reset above carries an ID (1-0-1-0), so every state rule below must
     also carry it or the reset out-ranks the state. */
  .nav-links--link:hover,
  .left-sidebar .nav-links--link:hover,
  #left-sidebar .nav-links--link:hover,
  #left-sidebar .nav-links .nav-links--link:hover {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* Selected nav item: SE marks it `aria-current="page"` (`.youarehere` is gone).
     Must out-rank both the ID-carrying at-rest reset and the hover rule, so it
     repeats `#left-sidebar` and sits after them. */
  .left-sidebar .nav-links--link.youarehere,
  .left-sidebar .nav-links--link.youarehere .-link,
  .nav-links--link[aria-current="page"],
  .nav-links--link[aria-current="true"],
  .left-sidebar .nav-links--link[aria-current="page"],
  #left-sidebar .nav-links--link[aria-current="page"],
  #left-sidebar .nav-links--link[aria-current="true"],
  #left-sidebar .nav-links .nav-links--link[aria-current="page"] {
    background-color: #1c2128 !important;
    border-left: 3px solid #d98b3a !important;
    color: #e6edf3 !important;
  }

  #left-sidebar .nav-links .nav-links--link[aria-current="page"]:hover,
  #left-sidebar .nav-links--link[aria-current="page"]:hover {
    background-color: #21262d !important;
  }

  /* keep the selected item's label bright (over the generic muted nav-link colour) */
  .nav-links--link[aria-current="page"],
  .nav-links--link[aria-current="page"] .-link--channel-name,
  .nav-links--link:hover .-link--channel-name {
    color: #e6edf3 !important;
  }

  /* Purple brand-icon discs: a white glyph on a purple disc ringed by a 4px
     near-white `.bc-purple-200` border that halos on dark — retone only the ring. The
     disc FILL is pinned to the #555bce it already computes to on the light site, so
     it is a no-op there but keeps the glyph legible for a reader who also runs SE's
     account-level dark mode, where --purple-400 flips pale. */
  .nav-links--link .bg-purple-400.bar-circle,
  .nav-links--link div.bg-purple-400,
  .left-sidebar .nav-links--link .bg-purple-400 {
    background-color: #555bce !important;
    border-color: #3b3f73 !important;
  }

  /* Nav item GLYPHS take a raw `var(--black-500)`, not an `.fc-black-*` utility, so
     no utility remap reaches them. They are `fill:currentColor`, so `color` suffices;
     `:not(.fc-white)` spares the purple discs' white glyphs. */
  .nav-links--link .svg-icon:not(.fc-white),
  .nav-links--link.-link__with-icon .svg-icon:not(.fc-white),
  .left-sidebar .nav-links--link .svg-icon:not(.fc-white) {
    color: #9198a1 !important;
  }

  .nav-links--link:hover .svg-icon:not(.fc-white),
  .nav-links--link[aria-current="page"] .svg-icon:not(.fc-white),
  .left-sidebar .nav-links--link[aria-current="page"] .svg-icon:not(.fc-white) {
    color: #e6edf3 !important;
  }

  /* SE plates the glyph itself on hover/focus/active from a raw `--black-100`. Keep
     the plate one step above the row's hover surface. */
  .nav-links .nav-links--link.-link__with-icon:hover .svg-icon:not(.fc-white),
  .nav-links .nav-links--link.-link__with-icon:focus .svg-icon:not(.fc-white),
  .nav-links .nav-links--link.-link__with-icon:active .svg-icon:not(.fc-white) {
    background-color: #2d333b !important;
  }

  /* Main content: question / answers / cards */
  #content,
  #question-header,
  .question-page #mainbar,
  .inner-content {
    background-color: transparent !important;
  }

  /* The smaller network sites box #content in a light 1px border; SO has none. */
  #content {
    border-color: #262c33 !important;
  }

  /* Cards & elevated panels */
  .s-card,
  .js-post-summary,
  .question-summary,
  .spacer .grid--cell,
  .s-modal--dialog,
  .popup,
  .s-popover,
  .module.community-bulletin,
  .s-notice {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* The question + each answer cell */
  #question,
  .question,
  .answer,
  .post-layout,
  .js-zone-container,
  #answers,
  .answercell,
  .postcell,
  .post-layout--right,
  .post-layout--left {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* dividers between posts */
  .question, .answer,
  .pb8.mb16.bb.bc-black-075,
  .bb.bc-black-075, .bb.bc-black-100,
  .bt.bc-black-075, .bt.bc-black-100,
  #answers-header {
    border-color: #262c33 !important;
  }

  /* Prose body text */
  .s-prose,
  .post-text,
  .js-post-body,
  .comment-copy,
  .wmx100 {
    color: #c4cdd6 !important;
  }

  .s-prose strong, .s-prose b { color: #e6edf3 !important; }

  /* …but not when the bold text IS the link: the bright-prose rules are !important
     and land on the inner element, so the anchor's accent would never reach it. Same
     trap for the metadata `strong` rules below, hence the `.post-layout` /
     `.grid--cell` arms. */
  .s-prose a strong, .s-prose a b,
  .comment-copy a strong, .comment-copy a b,
  .post-layout a strong, .grid--cell a strong {
    color: inherit !important;
  }

  /* Stacks draws a quote's left rule as a 4px `::before` fill, NOT as a border —
     `border-left-width` is 0, so a border-colour override alone is a no-op. */
  .s-prose blockquote {
    border-left-color: #2d333b !important;
    color: #9198a1 !important;
  }

  .s-prose blockquote::before,
  blockquote::before {
    background-color: #3d444d !important;
  }

  /* SE draws every <hr> as a 1px block with a `background-color` and
     `border-width: 0`, so a border-color override never paints. */
  hr,
  .s-prose hr,
  .s-card hr {
    background-color: #262c33 !important;
    border-color: #262c33 !important;
  }

  /* Section rules drawn as a BORDER, not an <hr>: `.s-page-title` and each
     help-center category <h3>, both light-theme greys SE never re-tones. */
  .s-page-title,
  div.s-page-title,
  .help-category-box h3,
  .help-center-index h3,
  .help-category-box > h3 {
    border-color: #2d333b !important;
  }

  /* The `.s-page-title` breadcrumb and standfirst take raw tokens no `.fc-black-*`
     remap reaches, and a breadcrumb link flips to `--_br-link-fc` at 1.5:1 ON
     HOVER. */
  .s-breadcrumbs--link,
  .s-breadcrumbs .s-breadcrumbs--link,
  .s-page-title--description,
  .s-page-title .s-page-title--description {
    color: #9198a1 !important;
  }

  .s-breadcrumbs--link:hover,
  .s-breadcrumbs .s-breadcrumbs--link:hover {
    color: #c4cdd6 !important;
  }

  /* Accepted answer highlight */
  .answer.accepted-answer,
  .accepted-answer {
    background-color: #16221a !important;
  }

  .accepted-answer .js-vote-count,
  .accepted-answer .vote-count-post {
    color: #e6edf3 !important;
  }

  /* Stacks semantic TEXT tones (`--fc-success` / `--fc-error` / `--fc-danger` /
     `--fc-warning`) were picked for the white site and land under AA here. The
     matching `.bg-*` / `.bc-*` utilities are solid fills that already read on dark
     and keep the site value. */
  .fc-success {
    color: #3fb950 !important;
  }

  .fc-error,
  .fc-danger {
    color: #f85149 !important;
  }

  .fc-warning {
    color: #d98b3a !important;
  }

  /* The accepted (green check) glyph */
  .accepted-answer-indicator,
  .js-accepted-answer-indicator,
  .iconCheckmarkLg.fc-green-400,
  svg.fc-green-500 {
    color: #3fb950 !important;
  }

  /* Vote controls */
  .js-vote-count,
  .vote-count-post,
  .js-voting-container .fc-black-500 {
    color: #e6edf3 !important;
  }

  .js-vote-up-btn, .js-vote-down-btn,
  .vote-up-off, .vote-down-off,
  .s-btn.s-btn__unset.c-pointer {
    color: #9198a1 !important;
  }

  /* The vote arrows signal the click with the theme orange. They are also
     `.s-btn.s-btn__muted`, so the generic `.s-btn:hover` grey below — same
     specificity, later — wins unless restated at 2 classes plus the element. */
  .js-vote-up-btn:hover, .js-vote-down-btn:hover,
  .s-btn.js-vote-up-btn:hover, .s-btn.js-vote-down-btn:hover,
  button.s-btn.js-vote-up-btn:hover, button.s-btn.js-vote-down-btn:hover {
    background-color: rgba(217, 139, 58, 0.18) !important;
    color: #d98b3a !important;
  }

  /* The button is `.s-btn__outlined.s-btn__muted`, a 3-class rule LATER in this file
     than the hover rule above, so the element qualifier is what lifts these past
     it. */
  button.s-btn.js-vote-up-btn:hover,
  button.s-btn.js-vote-down-btn:hover,
  button.s-btn.js-vote-up-btn:hover .svg-icon,
  button.s-btn.js-vote-down-btn:hover .svg-icon {
    color: #d98b3a !important;
  }

  .js-vote-up-btn.fc-theme-primary,
  .vote-up-on,
  .js-voting-container .fc-orange-400 {
    color: #d98b3a !important;
  }

  /* Bookmark / star */
  .js-bookmark-btn.s-btn__filled,
  .js-saves-btn {
    color: #d98b3a !important;
  }

  /* Comments */
  .comments,
  .comment,
  .comment-text,
  .comments-list,
  .js-comments-container {
    background-color: transparent !important;
    border-color: #262c33 !important;
  }

  .comment {
    border-bottom: 1px solid #20262d !important;
  }

  /* comment action rows carry a light #c4cdd6 border-bottom */
  .comment-actions,
  .js-comment-actions {
    border-color: #20262d !important;
  }

  .comment-copy { color: #b3bcc6 !important; }

  .comment .comment-user,
  .comment a.comment-user {
    color: #6f9ab0 !important;
  }

  /* The post owner's comment name carries `.owner`, which SE highlights with a
     light-blue pill. The bare arms carry it to the post timeline, outside any
     `.comment`. */
  .comment .comment-user.owner,
  .comment a.comment-user.owner,
  .comment-user.owner,
  a.comment-user.owner {
    background-color: #16202c !important;
  }

  /* SE pins `.comment-date` and its anchor to `var(--black-400)` with its own
     !important at 2 classes, and `a .relativetime-clean { inherit }` above hands that
     to the date span. Mirror SE's specificity. */
  .comment-date,
  .comment-date > a,
  .comment-date a.comment-link {
    color: #9198a1 !important;
  }

  .comment-score, .comment-score b {
    color: #9198a1 !important;
  }

  /* Comment-score tiers: SE's `.warm` is a dark brown and `.cool` its muted grey;
     `.hot` is lifted by its own rule. Keep warm distinct from hot. */
  .comment-score .warm, .comment-score.warm,
  .comment-actions .warm {
    color: #d98b3a !important;
  }

  .comment-score .cool, .comment-score.cool,
  .comment-actions .cool {
    color: #9198a1 !important;
  }

  .comment-actions .comment-up-on,
  .comment-up:hover {
    color: #d98b3a !important;
  }

  /* "Add a comment" / show more comments link */
  .js-add-link, .js-show-link, .js-link-separator {
    color: #5fb0e6 !important;
  }

  /* Tags */
  .post-tag,
  .s-tag,
  a.post-tag,
  a.s-tag,
  .badge-tag,
  a.badge-tag {
    background-color: #20303d !important;
    color: #8cc6f0 !important;
    border-color: #2b4253 !important;
  }

  .post-tag:hover,
  .s-tag:hover,
  a.post-tag:hover,
  a.badge-tag:hover {
    background-color: #2b4253 !important;
    color: #bfe0f7 !important;
  }

  .s-tag.s-tag__moderator { background-color: #3a2b20 !important; color: #e0a878 !important; }

  /* Tag count / multiplier badges: the `×` glyph is a SEPARATE element from the
     number beside it, so both halves of one label must move together. */
  .s-tag--count, .post-tag-count,
  .item-multiplier,
  .item-multiplier-x,
  .item-multiplier-count,
  .item-multiplier .item-multiplier-count { color: #9198a1 !important; }

  /* Code blocks + inline code + syntax highlighting */
  pre,
  pre.s-code-block,
  .s-code-block,
  .s-prose pre,
  .wmd-preview pre {
    background-color: #222831 !important;
    color: #d9e0e7 !important;
    border: 1px solid #2d333b !important;
  }

  pre code, .s-code-block code {
    background-color: transparent !important;
    color: #d9e0e7 !important;
  }

  /* inline code */
  code,
  .s-prose code,
  kbd {
    background-color: #232a33 !important;
    color: #e3b7a0 !important;
  }

  kbd {
    border-color: #2d333b !important;
    color: #d9e0e7 !important;
    box-shadow: none !important;
  }

  /* highlight.js dark syntax palette */
  .hljs { background: transparent !important; color: #d9e0e7 !important; }
  .hljs-comment, .hljs-quote { color: #8b949e !important; }
  .hljs-keyword, .hljs-selector-tag, .hljs-built_in,
  .hljs-name, .hljs-tag { color: #ff7b72 !important; }
  .hljs-string, .hljs-attr, .hljs-template-tag,
  .hljs-addition, .hljs-regexp { color: #a5d6ff !important; }
  .hljs-number, .hljs-literal, .hljs-type,
  .hljs-variable, .hljs-template-variable,
  .hljs-class .hljs-title, .hljs-selector-attr,
  .hljs-selector-pseudo { color: #79c0ff !important; }
  .hljs-title, .hljs-function .hljs-title, .hljs-section { color: #d2a8ff !important; }
  .hljs-attribute, .hljs-symbol, .hljs-bullet,
  .hljs-meta { color: #ffa657 !important; }
  .hljs-deletion { color: #ff7b72 !important; }
  .hljs-emphasis { font-style: italic; }
  .hljs-strong { font-weight: bold; color: #e6edf3 !important; }
  .hljs-doctag, .hljs-params { color: #c4cdd6 !important; }
  /* Tokens the palette above did not name. SE's rules for these out-specify `.hljs`
     (0,2,2), so an unlisted token silently keeps its LIGHT-theme colour. */
  .hljs-subst { color: #d9e0e7 !important; }
  .hljs-code { color: #c4cdd6 !important; }
  .hljs-link, .hljs-meta-string { color: #a5d6ff !important; }
  .hljs-meta-keyword, .hljs-selector-class { color: #ff7b72 !important; }
  .hljs-selector-id { color: #79c0ff !important; }

  /* Stacks prettify-style spans (older code) */
  .prettyprint .pln { color: #d9e0e7 !important; }
  .prettyprint .str, .prettyprint .atv { color: #a5d6ff !important; }
  .prettyprint .kwd { color: #ff7b72 !important; }
  .prettyprint .com { color: #8b949e !important; }
  .prettyprint .typ, .prettyprint .atn { color: #79c0ff !important; }
  .prettyprint .lit { color: #79c0ff !important; }
  .prettyprint .pun, .prettyprint .opn, .prettyprint .clo { color: #c4cdd6 !important; }
  .prettyprint .tag { color: #ff7b72 !important; }

  /* Right sidebar modules (Linked / Related / Hot / Featured) */
  #sidebar,
  .sidebar,
  #sidebar .module,
  .module.sidebar-linked,
  .module.sidebar-related,
  .module.sidebar-featured,
  .module.community-bulletin,
  .module.newsletter-ad,
  .s-sidebarwidget,
  .s-sidebarwidget--content {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .s-sidebarwidget {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .s-sidebarwidget--header,
  .s-sidebarwidget .s-sidebarwidget--header {
    background-color: #20262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Hot Network Questions (yellow widget) -> warm-tinted dark */
  .s-sidebarwidget__yellow,
  .s-sidebarwidget.s-sidebarwidget__yellow {
    background-color: #211d14 !important;
    border-color: #3a3320 !important;
  }

  /* Widget headers: ONE treatment across page types — SE renders the yellow one gold
     and the rest near-black. */
  .s-sidebarwidget__yellow .s-sidebarwidget--header,
  .s-sidebarwidget .s-sidebarwidget--header {
    background-color: #20262d !important;
    color: #e8c98a !important;
  }

  /* "Hot Network Questions" is a legacy `.module`, not an `.s-sidebarwidget`, so its
     <h4> belongs with Linked/Related, not the gold band. The only hook is the ID, and
     the heading text is an <a> SE opts out of the link colour with `.s-link__inherit`,
     which our `#sidebar a` accent overrides. */
  #hot-network-questions h4,
  #hot-network-questions h4 a,
  #hot-network-questions h4 a.s-link__inherit {
    color: #e6edf3 !important;
  }

  /* Otherwise this band takes the generic `.s-sidebarwidget--header` border and
     draws a cold neutral line across a warm card. */
  .s-sidebarwidget__yellow .s-sidebarwidget--header,
  .s-sidebarwidget.s-sidebarwidget__yellow .s-sidebarwidget--header {
    background-color: #2a2417 !important;
    border-color: #3a3320 !important;
  }

  /* The band fill above assumes the header is the widget's full-width `li`;
     "Community activity" puts it on an INLINE div in a flex row, where the fill stops
     dead mid-row. */
  .s-sidebarwidget div.s-sidebarwidget--header,
  .s-sidebarwidget div.s-sidebarwidget--header.s-sidebarwidget--header {
    background-color: transparent !important;
  }

  /* `.s-anchors__grayscale` forces these links dark via `-webkit-text-fill-color`,
     NOT plain `color`, so both must be set. */
  #sidebar .s-anchors__grayscale a,
  #sidebar .s-sidebarwidget__yellow a,
  #sidebar .s-sidebarwidget a.js-gps-track,
  .s-sidebarwidget.s-anchors__grayscale a {
    color: #5fb0e6 !important;
    -webkit-text-fill-color: #5fb0e6 !important;
  }

  #sidebar .s-anchors__grayscale a:hover,
  #sidebar .s-sidebarwidget__yellow a:hover,
  #sidebar .s-sidebarwidget a.js-gps-track:hover {
    color: #9bd4ff !important;
    -webkit-text-fill-color: #9bd4ff !important;
  }

  .module.sidebar-linked .spacer .answered,
  .module.sidebar-related .spacer .answered-accepted,
  #sidebar .answered,
  #sidebar .unanswered {
    color: #c4cdd6 !important;
  }

  #sidebar .question-hyperlink,
  #sidebar a {
    color: #5fb0e6 !important;
  }

  /* SE fills the accepted-answer pill solid green with white text everywhere, so the
     sidebar pills must not render that state as a faint tint. */
  #sidebar .answered-accepted, #sidebar .accepted {
    background-color: #1f7a45 !important;
    color: #ffffff !important;
  }

  #sidebar .answered {
    background-color: #20303d !important;
    color: #8cc6f0 !important;
  }

  /* `default` / `large` / `extra-large` are SIZE classes, NOT states: match the STATE
     only, or the white pill returns one size up. ACCEPTED and ANSWERED pills keep
     their fill, and these selectors would out-specify the state rules below, so both
     are excluded explicitly. */
  .answer-votes:not(.answered):not(.answered-accepted),
  #sidebar .answer-votes:not(.answered):not(.answered-accepted),
  .module .answer-votes:not(.answered):not(.answered-accepted) {
    background-color: #20262d !important;
    color: #9198a1 !important;
  }

  #sidebar .status.unanswered, #sidebar .iconClock {
    color: #9198a1 !important;
  }

  /* "Featured on Meta" / list rows */
  .s-sidebarwidget--item,
  .s-sidebarwidget .s-sidebarwidget--item {
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* Stacks separates two stacked `--content` blocks with a `--black-150` top rule
     on the second (`+` sibling), a path the `--item` arm above never reaches. */
  .s-sidebarwidget--content,
  .s-sidebarwidget .s-sidebarwidget--content {
    border-color: #2d333b !important;
  }

  /* Inside the yellow widget those same rules are warm; three classes to out-rank
     the `--content.__item` arms later in the file. */
  .s-sidebarwidget.s-sidebarwidget__yellow .s-sidebarwidget--content,
  .s-sidebarwidget.s-sidebarwidget__yellow .s-sidebarwidget--item {
    border-color: #3a3320 !important;
  }

  /* Stacks de-links plain anchors inside a sidebar widget
     (`:not(.s-anchors) a:not(…)` -> `--black-600`): they are the widget's PROMINENT
     ink, not the accent, and that five-way `:not()` chain out-ranks the page accent
     wherever `#sidebar` is absent (/legal). Map the ink, not the link colour. */
  .s-sidebarwidget--item a,
  .s-sidebarwidget--content a {
    color: #e6edf3 !important;
  }

  .s-sidebarwidget--item a:hover,
  .s-sidebarwidget--content a:hover {
    color: #9bd4ff !important;
  }

  /* Questions list / home */
  .s-post-summary,
  .js-post-summary,
  .question-summary,
  .s-post-summary--content {
    background-color: transparent !important;
    border-color: #262c33 !important;
  }

  .s-post-summary {
    border-bottom: 1px solid #20262d !important;
  }

  .s-post-summary--content-title a,
  .s-post-summary .question-hyperlink {
    color: #c8d6f0 !important;
  }

  .s-post-summary--content-title a:hover { color: #9bd4ff !important; }

  .s-post-summary--content-excerpt { color: #9198a1 !important; }

  /* vote / answer / view stat pills */
  .s-post-summary--stats-item,
  .s-post-summary--stats-item-number,
  .stats .vote-count-post,
  .stats .views {
    color: #9198a1 !important;
  }

  /* The `.is-warm` / `.is-hot` / `.is-supernova` heat tiers are the only trending
     signal on a list row, and the blanket stats-item mute flattens all three. */
  .s-post-summary--stats-item.is-warm,
  .s-post-summary--stats-item.is-warm .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.is-warm .s-post-summary--stats-item-unit {
    color: #d3a84a !important;
  }

  .s-post-summary--stats-item.is-hot,
  .s-post-summary--stats-item.is-hot .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.is-hot .s-post-summary--stats-item-unit {
    color: #e0913f !important;
  }

  .s-post-summary--stats-item.is-supernova,
  .s-post-summary--stats-item.is-supernova .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.is-supernova .s-post-summary--stats-item-unit {
    color: #f0776b !important;
  }

  /* "answered & accepted" pill: filled green with white text
     (matches SE), readable contrast. */
  .s-post-summary--stats-item.has-answers.has-accepted-answer,
  .s-post-summary--stats-item.has-accepted-answer,
  .status.answered-accepted {
    background-color: #1f7a45 !important;
    border-color: #1f7a45 !important;
    color: #ffffff !important;
  }

  .s-post-summary--stats-item.has-answers.has-accepted-answer .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.has-accepted-answer .s-post-summary--stats-item-unit,
  .status.answered-accepted strong,
  .status.answered-accepted .strunk {
    color: #ffffff !important;
  }

  /* "answered" (no accept) pill: green outline */
  .s-post-summary--stats-item.has-answers:not(.has-accepted-answer),
  .status.answered {
    border-color: #2b6e44 !important;
    color: #8fdc9e !important;
  }

  /* The count NUMBER inside the "answered" pill has its own muted-grey
     `.s-post-summary--stats-item-number` rule that beats the green above. */
  .s-post-summary--stats-item.has-answers:not(.has-accepted-answer) .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.has-answers:not(.has-accepted-answer) .s-post-summary--stats-item-unit {
    color: #8fdc9e !important;
  }

  /* The BOUNTY pill is a `.s-post-summary--stats-item`, so the muted-grey rule
     flattens SE's WHITE label on its blue chip. The fill is SE's own and stays. */
  .s-post-summary--stats-item.has-bounty,
  .s-post-summary--stats-item.has-bounty .s-post-summary--stats-item-number,
  .s-post-summary--stats-item.has-bounty .s-post-summary--stats-item-unit {
    color: #ffffff !important;
  }

  /* The tab GROUP has a real frame natively; its ITEMS carry `1px solid transparent`
     for layout only, so only their label colour belongs here — a hairline per item
     draws a box the site never draws. */
  .s-btn-group .s-btn {
    color: #c4cdd6 !important;
  }

  .s-btn.s-btn__muted.s-btn__outlined,
  .youarehere,
  .js-filter-btn {
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  .s-btn-group .s-btn.is-selected,
  .s-btn-group .s-btn[aria-pressed="true"],
  .nav-tabs .youarehere {
    background-color: #20303d !important;
    color: #bfe0f7 !important;
    border-color: #2b4253 !important;
  }

  /* The subtabs are bare <a> wrapping an inner `.s-btn--text` span, and SE marks the
     SELECTED one with blue text plus an underline that the `.youarehere` reset and
     the `.s-btn--text` mute would flatten. The span needs its own selector:
     `.s-btn--text` colours the label. */
  .subtabs a,
  .subtabs a .s-btn--text {
    color: #9198a1 !important;
  }

  .subtabs a:hover,
  .subtabs a:hover .s-btn--text {
    color: #c4cdd6 !important;
  }

  .subtabs .youarehere.is-selected,
  .subtabs .youarehere .s-btn--text {
    color: #6fb3e8 !important;
  }

  .subtabs .youarehere.is-selected {
    border-bottom-color: #5fb0e6 !important;
  }

  /* Buttons */
  .s-btn__primary,
  .s-btn.s-btn__primary,
  .s-btn__primary .s-btn__inner,
  .s-btn__filled,
  .s-btn.s-btn__filled {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
    border-color: #3b82b8 !important;
  }

  /* This must out-rank BOTH the generic `.s-btn:hover` mute below (equal
     specificity, later) AND the 3-class `.s-btn.s-btn__primary.ws-nowrap` fill at the
     end of this section — hence the element-qualified arms. */
  .s-btn.s-btn__primary:hover,
  .s-btn.s-btn__filled:hover,
  a.s-btn.s-btn__primary:hover,
  a.s-btn.s-btn__filled:hover,
  button.s-btn.s-btn__primary:hover,
  button.s-btn.s-btn__filled:hover { background-color: #3b82b8 !important; color: #fff !important; }

  .s-btn,
  .s-btn__muted,
  .s-btn__outlined {
    color: #c4cdd6 !important;
  }

  .s-btn:hover,
  .s-btn__muted:hover {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* A BARE `.s-btn` with no variant modifier is Stacks' tertiary action: link-blue
     on no fill. Every modifier carrying its own ink is excluded, as are the topbar /
     modal-close / pressed shapes and anything with an `.fc-*` utility. The `:not()`
     chain out-weighs `.s-btn:hover`, so the hover ink is restated. */
  .s-btn:not(.s-btn__muted):not(.s-btn__outlined):not(.s-btn__filled):not(.s-btn__primary):not(.s-btn__unset):not(.s-btn__link):not(.s-btn__google):not(.s-btn__github):not(.s-btn__facebook):not(.s-btn__danger):not(.s-btn__featured):not(.is-selected):not(.s-topbar--item):not(.s-topbar--menu-btn):not(.s-modal--close):not([class*="fc-"]) {
    color: #5fb0e6 !important;
  }

  .s-btn:not(.s-btn__muted):not(.s-btn__outlined):not(.s-btn__filled):not(.s-btn__primary):not(.s-btn__unset):not(.s-btn__link):not(.s-btn__google):not(.s-btn__github):not(.s-btn__facebook):not(.s-btn__danger):not(.s-btn__featured):not(.is-selected):not(.s-topbar--item):not(.s-topbar--menu-btn):not(.s-modal--close):not([class*="fc-"]):hover {
    color: #9bd4ff !important;
  }

  /* A pressed toggle outside an `.s-btn-group` fills from `--_bu-bg-selected` /
     `--_bu-fc-selected`, with no `.bg-black-*` utility on the element, so nothing
     else here reaches it. `__filled` / `__primary` keep their own selected tokens.
     The hover arm is required or the mute above strips the pressed fill on
     pointer-over. */
  .s-btn.is-selected:not(.s-btn__filled):not(.s-btn__primary),
  .s-btn.is-selected:not(.s-btn__filled):not(.s-btn__primary):hover,
  .s-btn--radio:checked + .s-btn {
    background-color: #20303d !important;
    color: #bfe0f7 !important;
  }

  .s-btn__outlined {
    border-color: #2d333b !important;
  }

  /* Stacks is BEM: every `.s-btn__<variant>` only sets custom properties the base
     `.s-btn` rule consumes, so our base-class !important beats them all. Restored at
     2 classes. */

  /* OAuth buttons are brand assets (SE's own dark theme keeps them): white Google,
     near-black GitHub, blue Facebook. */
  .s-btn.s-btn__google {
    color: #3b4045 !important;
  }

  .s-btn.s-btn__github,
  .s-btn.s-btn__facebook {
    color: #ffffff !important;
  }

  /* `.s-btn:hover` ties on specificity with the 2-class rest rules above, which are
     declared later, so each variant needs its own hover fill. */
  .s-btn.s-btn__google:hover {
    background-color: #f1f2f3 !important;
    color: #3b4045 !important;
  }

  .s-btn.s-btn__github:hover {
    background-color: #0c0d0e !important;
    color: #ffffff !important;
  }

  .s-btn.s-btn__facebook:hover {
    background-color: #314a86 !important;
    color: #ffffff !important;
  }

  /* Link-styled buttons are blue links natively; the post-menu ones (Share / Follow)
     are deliberately muted grey and stay so. */
  .s-btn.s-btn__link {
    color: #5fb0e6 !important;
  }

  /* The post menu mixes `.s-btn__link` buttons with bare anchors on SE's raw
     `--black-400`. Both are the same control row and must read the same. */
  .js-post-menu .s-btn.s-btn__link,
  .post-menu .s-btn.s-btn__link,
  .post-menu a.c-default,
  .js-post-menu a.c-default {
    color: #9198a1 !important;
  }

  /* …except "Copy link", inside the share popover the post menu owns, which the mute
     above swallows; it is an action SE paints link blue. */
  .js-post-menu .s-btn.s-btn__link.js-copy-link-btn,
  .post-menu .s-btn.s-btn__link.js-copy-link-btn {
    color: #5fb0e6 !important;
  }

  /* …and the "CC BY-SA 4.0" link beside it is an <a>, not a `.s-btn`, so none of the
     rules above reach it. */
  .share-sheet-popover a.js-license,
  .s-popover a.js-license {
    color: #5fb0e6 !important;
  }

  /* Stacks also link-styles a button by adding `.s-link` alongside the button
     classes, and our 1-class `.s-btn__muted` / `.s-btn` rules out-rank SE's link
     colour. Match on the `.s-link` pairing, not any one named class, so a rename
     cannot break it. */
  .s-link.s-btn,
  .s-link.s-btn__muted,
  .s-link.s-btn__outlined,
  .comments-link {
    color: #5fb0e6 !important;
  }

  /* Outlined CTAs ("Log in", "Ask question") are the accent colour; only
     the muted variant is grey. */
  .s-btn.s-btn__outlined {
    color: #5fb0e6 !important;
    border-color: #3b82b8 !important;
  }

  .s-btn.s-btn__outlined.s-btn__muted {
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* An outlined button TOGGLED OPEN gets `.is-selected`, which SE fills pale blue —
     the outlined-CTA accent would then be light blue on light blue. */
  .s-btn.s-btn__outlined.is-selected,
  .s-btn.s-btn__outlined.is-selected:hover {
    background-color: #20303d !important;
    color: #bfe0f7 !important;
    border-color: #2b4253 !important;
  }

  /* Destructive + neutral-filled variants */
  .s-btn.s-btn__danger {
    color: #f0a8a8 !important;
  }

  .s-btn.s-btn__danger.s-btn__filled {
    background-color: #8b2c31 !important;
    color: #ffffff !important;
    border-color: #a03a40 !important;
  }

  .s-btn.s-btn__filled.s-btn__muted {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
    border-color: #3d444d !important;
  }

  /* `__featured` is the last `.s-btn__<variant>`: a purple promo CTA the base
     `.s-btn` grey flattens like the rest of the family. */
  .s-btn.s-btn__featured {
    color: #a8abf2 !important;
  }

  .s-btn.s-btn__featured.s-btn__outlined {
    color: #a8abf2 !important;
    border-color: #5a5fc0 !important;
  }

  .s-btn.s-btn__featured.s-btn__filled {
    background-color: #4a4fa8 !important;
    color: #ffffff !important;
    border-color: #5a5fc0 !important;
  }

  /* Stacks fills `.s-btn .s-btn--badge` from `background-color: currentColor` and SO
     also stamps `.bg-blue-500`, which our banner retone swallows; the legacy
     `.bounty-indicator*` chip is the SAME control on the other sites, so both are
     pinned to one fill. `.bounty-indicator-tab.flagbg` (red) is 2 classes and
     !important in SE's sheet, so it still wins. */
  .s-btn-group .s-btn .s-btn--badge,
  .s-btn--badge.bg-blue-500,
  .s-btn--badge.bg-blue-400,
  .s-btn--badge.bg-blue-600,
  .bounty-indicator,
  .bounty-indicator-tab {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
  }

  /* "Ask Question" big button */
  .ask-question-btn, .s-btn.s-btn__primary.ws-nowrap {
    background-color: #2f6f9f !important;
  }

  /* Notices, callouts, badges */
  .s-notice,
  .s-notice__info {
    background-color: #14222e !important;
    border-color: #234055 !important;
    color: #bcd3e6 !important;
  }

  .s-notice__warning,
  .s-notice.s-notice__warning {
    background-color: #2a2114 !important;
    border-color: #4a3a1c !important;
    color: #e8c98a !important;
  }

  .s-notice__danger,
  .s-notice__important {
    background-color: #2a1718 !important;
    border-color: #5a2a2c !important;
    color: #f0a8a8 !important;
  }

  .s-notice__success {
    background-color: #16221a !important;
    border-color: #25402d !important;
    color: #aee0bb !important;
  }

  /* Legacy `.val-message` validation banners predate `.s-notice`: cream / pale
     yellow / pale red with near-black text. The cream's blue channel (198) sneaks
     under a >200 near-white threshold. */
  .val-message,
  .val-message.val-info {
    background-color: #221d14 !important;
    border-color: #3a3320 !important;
    color: #e8c98a !important;
  }

  .val-message.val-warning {
    background-color: #2a2114 !important;
    border-color: #4a3a1c !important;
    color: #e8c98a !important;
  }

  .val-message.val-error {
    background-color: #2a1718 !important;
    border-color: #5a2a2c !important;
    color: #f0a8a8 !important;
  }

  .val-message a { color: #5fb0e6 !important; }

  .s-badge,
  .s-badge__bounty {
    background-color: #20303d !important;
    color: #8cc6f0 !important;
    border-color: #2b4253 !important;
  }

  /* Same BEM trap as the buttons: every `.s-badge__<variant>` only sets --_ba-bg /
     --_ba-fc, so the base rule flattens the family. Restored at 2 classes. */
  .s-badge.s-badge__answered {
    background-color: #1f7a45 !important;
    color: #ffffff !important;
    border-color: #1f7a45 !important;
  }

  .s-badge.s-badge__bounty {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
    border-color: #3b82b8 !important;
  }

  .s-badge.s-badge__important {
    background-color: #8b2c31 !important;
    color: #ffffff !important;
    border-color: #8b2c31 !important;
  }

  .s-badge.s-badge__rep {
    background-color: transparent !important;
    color: #8fdc9e !important;
    border-color: #2b6e44 !important;
  }

  .s-badge.s-badge__rep-down {
    background-color: transparent !important;
    color: #f0a8a8 !important;
    border-color: #5a2a2c !important;
  }

  .s-badge.s-badge__gold {
    background-color: #2a2417 !important;
    color: #e8c98a !important;
    border-color: #6b5518 !important;
  }

  .s-badge.s-badge__silver {
    background-color: #24282c !important;
    color: #c0c6cc !important;
    border-color: #5a6068 !important;
  }

  .s-badge.s-badge__bronze {
    background-color: #2a2018 !important;
    color: #d0a07a !important;
    border-color: #6b4a30 !important;
  }

  .s-badge.s-badge__danger {
    background-color: #2a1718 !important;
    color: #f0a8a8 !important;
    border-color: #5a2a2c !important;
  }

  .s-badge.s-badge__warning {
    background-color: #2a2114 !important;
    color: #e8c98a !important;
    border-color: #4a3a1c !important;
  }

  .s-badge.s-badge__staff,
  .s-badge.s-badge__admin,
  .s-badge.s-badge__moderator {
    background-color: #3a2b20 !important;
    color: #e0a878 !important;
    border-color: #5a4326 !important;
  }

  .s-badge.s-badge__new {
    background-color: #221c2e !important;
    color: #c0a8e8 !important;
    border-color: #3a2f55 !important;
  }

  /* The rest of the `.s-badge__*` family, same BEM trap (22 variants ship, 13 named
     above). `__votes` mirrors SE's `:not(.s-badge__answered)` guard so the green
     survives; `__danger.__filled` is needed because the 2-class `__danger` rule above
     sets background-color directly and beats SE's 3-class token rule. Size modifiers
     stay untouched. */
  .s-badge.s-badge__votes:not(.s-badge__answered) {
    background-color: #20262d !important;
    color: #9198a1 !important;
    border-color: #2d333b !important;
  }

  .s-badge.s-badge__muted {
    background-color: #20262d !important;
    color: #9198a1 !important;
    border-color: #3d444d !important;
  }

  .s-badge.s-badge__muted.s-badge__filled {
    background-color: #3d444d !important;
    color: #ffffff !important;
    border-color: #3d444d !important;
  }

  .s-badge.s-badge__danger.s-badge__filled {
    background-color: #a03a40 !important;
    color: #ffffff !important;
    border-color: #a03a40 !important;
  }

  .s-badge.s-badge__info {
    background-color: #14222e !important;
    color: #8cc6f0 !important;
    border-color: #234055 !important;
  }

  .s-badge.s-badge__ai {
    background-color: #2a2114 !important;
    color: #e0913f !important;
    border-color: #e0913f !important;
  }

  .s-badge.s-badge__bot {
    background-color: #20262d !important;
    color: #c4cdd6 !important;
    border-color: #3d444d !important;
  }

  /* `.s-label--status` paints from `--_la-status-bg` / `--_la-status-fc` only, so no
     `.bg-*` / `.fc-*` remap reaches it; the tokens carry the variant semantics and
     the pill geometry. */
  .s-label--status {
    --_la-status-bg: #262c33 !important;
    --_la-status-fc: #c4cdd6 !important;
  }

  .s-label--status.s-label--status__beta {
    --_la-status-bg: #14222e !important;
    --_la-status-fc: #7cb7dd !important;
  }

  .s-label--status.s-label--status__new {
    --_la-status-bg: #14261c !important;
    --_la-status-fc: #8fdc9e !important;
  }

  .s-label--status.s-label--status__required {
    --_la-status-bg: #2d1a1a !important;
    --_la-status-fc: #f0a0a0 !important;
  }

  /* reputation / badge counts on user cards */
  .reputation-score, .user-info .reputation-score {
    color: #c4cdd6 !important;
  }

  /* `a.badge` sits on SE's own `--black-500` fill, a component surface we do not
     darken, so brighten the label instead. The `#sidebar` arm is required:
     `#sidebar a` out-specifies a bare `a.badge`, and the explainers live there. */
  a.badge,
  #sidebar a.badge {
    color: #7cc0ea !important;
  }

  .badgecount { color: #c4cdd6 !important; }
  .badge1, .badgecount .gold { color: #e8c98a !important; }
  .badge2, .badgecount .silver { color: #c0c6cc !important; }
  .badge3, .badgecount .bronze { color: #d0a07a !important; }

  /* user cards (signature blocks) */
  .post-signature,
  .user-info {
    color: #c4cdd6 !important;
  }

  /* `.s-avatar` fills its box from `--_av-bg: var(--_white-static)`, visible wherever
     the default silhouette avatar (a transparent canvas) is used. Retone the TOKEN,
     not `background-color`, so the corner radius and the 16-128 size modifiers keep
     working. */
  .s-avatar {
    --_av-bg: #262c33 !important;
  }

  /* Here the display name is a BARE <a> inside `.user-details`, not the Stacks
     `.s-user-card--link` handled above. */
  .user-details a,
  .post-signature .user-details a {
    color: #5fb0e6 !important;
  }

  .user-details a:hover,
  .post-signature .user-details a:hover {
    color: #9bd4ff !important;
  }

  /* The moderator diamond is a `<span>`, so it never picks up the anchor accent and
     keeps SE's raw `--theme-link-color`. */
  .mod-flair,
  span.mod-flair {
    color: #5fb0e6 !important;
  }

  /* SE tints ONLY `.post-signature.owner` — that tint marks which card is the
     author's, so `.user-info` must NOT take it. */
  .post-signature.owner,
  .post-signature.owner .user-info {
    background-color: #16202c !important;
    border-radius: 5px;
  }

  /* The "New contributor" pill is light blue with near-black `.fc-black-500` text,
     200x30 so it slips a height filter; the hand glyph rides on `.fc-black-500`
     too. */
  .new-contributor-indicator {
    background-color: #14222e !important;
    color: #bcd3e6 !important;
  }

  /* User profiles */
  .profile-card,
  .js-profile-card,
  .user-show-new .bg-white,
  #user-card,
  .userprofile {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .profile-header,
  .user-header {
    background-color: transparent !important;
  }

  /* Collectives / Communities cards: the collective NAME label keeps SE's
     near-black #0c0d0e on the card. */
  .subcommunity-topic-avatar .fs-body2,
  .subcommunity-topic-avatar .fs-body1,
  a.s-link__inherit .subcommunity-topic-avatar div {
    color: #e6edf3 !important;
  }

  /* The sparkline's gridlines are a repeating-linear-gradient BACKGROUND-IMAGE over
     a transparent background-COLOR. Repaint the bands only: the geometry is a
     separate longhand and the green `.line` stroke is untouched. */
  .profile-cards--graph,
  div.profile-cards--graph,
  .profile-cards--graph.js-reputation-graph {
    background-image: repeating-linear-gradient(0deg, transparent, transparent 13px, #2d333b -13px, #2d333b 21px) !important;
  }

  /* The progress TRACK is `--_pr-bg`, visible wherever the bar is unfilled (an
     anonymous visitor's privilege bars are ~0%). Darken the track token only;
     `--_pr-bar-bg` stays so the filled/empty split reads. */
  .s-progress {
    --_pr-bg: #2d333b !important;
  }

  /* Each medal variant fills the bar with a LIGHT metal tint while the label is
     absolutely positioned across the FULL width, so it must read over both halves.
     Retone each metal within its own hue family so the silver/gold/bronze signal
     survives; `--_pr-label-bc` is already dark enough. */
  .s-progress.s-progress__silver {
    --_pr-bar-bg: #4b5057 !important;
  }

  .s-progress.s-progress__gold {
    --_pr-bar-bg: #6b5713 !important;
  }

  .s-progress.s-progress__bronze {
    --_pr-bar-bg: #5f4531 !important;
  }

  /* The privilege variant fills with a near-white mint, same shape as the metals.
     Signed-in only, so fixed by the token path rather than verified live. */
  .s-progress.s-progress__privilege {
    --_pr-bar-bg: #1f7a45 !important;
  }

  .s-progress__badge .s-progress--label,
  .s-progress__privilege .s-progress--label {
    color: #e6edf3 !important;
  }

  /* Highcharts writes its colours as ATTRIBUTES and inline `style="fill:…"`, so only
     `fill:` / `stroke:` rules reach it: a class-less `<rect fill="var(--white)">`
     plate, a tooltip box that exists only while a bar is hovered, axis lines, and a
     #FFFFFF per-bar separator stroke. The --green-500 / --red-400 series ARE the data
     and stay; `.highcharts-tracker` rects are invisible hit targets. */
  .highcharts-container rect[fill="var(--white)"] {
    fill: #1c2128 !important;
  }

  .highcharts-container g.highcharts-series rect[stroke="#FFFFFF"] {
    stroke: #1c2128 !important;
  }

  .highcharts-container path[stroke="#C0D0E0"],
  .highcharts-container path[stroke="var(--black-300)"],
  .highcharts-container path[stroke="var(--black-350)"] {
    stroke: #2d333b !important;
  }

  /* Each `<text>` sets BOTH `fill` and `color` inline; only `fill` paints an SVG
     glyph, but pin `color` too — Highcharts switches the same label to HTML under
     `useHTML`. */
  .highcharts-container g.highcharts-axis text,
  .highcharts-container g.highcharts-axis tspan {
    fill: #9198a1 !important;
    color: #9198a1 !important;
  }

  /* The axis TITLE is a direct child of the <svg> and takes --blue-500, 2.4:1 once
     the plate is dark. */
  .highcharts-container > svg > text,
  .highcharts-container > svg > text tspan {
    fill: #5fb0e6 !important;
    color: #5fb0e6 !important;
  }

  .highcharts-container g.highcharts-tooltip text,
  .highcharts-container g.highcharts-tooltip tspan {
    fill: #e6edf3 !important;
    color: #e6edf3 !important;
  }

  /* …and the tooltip TEXT is not SVG: `useHTML` renders it as positioned `<span>`s
     on `color: var(--black-600)`, which no `fill:` rule reaches. */
  .highcharts-container > span,
  .highcharts-container > span span,
  .highcharts-container > span strong {
    color: #e6edf3 !important;
  }

  /* The series label ("rep:") is the span right after the <br> and takes the series
     colour --green-500, 1.9:1 on the dark box. */
  .highcharts-container > span > br + span {
    color: #3fb950 !important;
  }

  /* Tag pages */
  .tagged-questions,
  .tag-list .grid--cell,
  .js-tag-cell,
  .s-card.js-tag-cell {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* /tour is the only page family built from `.about-page .new-about-content-page`
     in `secondary.css`, so no Stacks card rule reaches it. It stages a mock question
     in `var(--white)` panels, and its headings take `--black-600` behind a 3-class
     !important that out-ranks the network-wide h1-h6 lift. */
  .qa-block,
  .content-block,
  .on-topic-examples,
  .off-topic-examples,
  .user-info-rep {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: none !important;
  }

  .about-page .new-about-content-page h2.about-title {
    color: #e6edf3 !important;
  }

  /* The mock post fades out under a white-to-transparent gradient standing in for
     "there is more text below". Its background-COLOR is never set. */
  .about-post-body-gradient {
    background: linear-gradient(to top, #1c2128 15%, rgba(28, 33, 40, 0)) !important;
  }

  .new-about-content-page .user-details,
  .new-about-content-page .rep-block,
  .new-about-content-page .comments,
  .new-about-content-page .rep-up-off {
    color: #9198a1 !important;
  }

  .new-about-content-page .rep-up {
    color: #3fb950 !important;
  }

  .new-about-content-page hr {
    background-color: #262c33 !important;
  }

  /* Search results page */
  .search-results,
  .js-search-results,
  #search-tab-questions,
  .search-result {
    background-color: transparent !important;
    border-color: #262c33 !important;
  }

  .search-results .question-summary {
    border-bottom: 1px solid #20262d !important;
  }

  /* search hint sidebar */
  .search-hints, .advanced-help {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* Network home (stackexchange.com) — bespoke layout
     Mixes shared Stacks components with bespoke markup (#question-list rows, #sideBar
     widgets, .featured-site, the legacy pager) no Stacks class rule reaches; its
     Stacks half rides the utility remaps above, `.fc-black` in particular. Several
     hooks below (.hero-box, .navMain, .subheader, .siteHeader h1, .sb-siteName,
     .stats-label, .module .heading) match nothing on the current page set and are
     kept as a fallback for older markup. */
  /* The network home wordmark is an unclassed <h1> with a CDN background-image logo
     baked for the white site: neither an <img> nor DOM text. */
  header.siteHeader .contentWrapper h1,
  .siteHeader h1 {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  .hero-box {
    background-color: #16202c !important;
    border-color: #234055 !important;
  }

  .hero-box .blurb,
  .hero-box .blurb em,
  .hero-box .blurb span {
    color: #c4cdd6 !important;
  }

  /* Hot / real-time rows also carry `box-shadow: 0 1px 0 #fff` — a pure-white 1px
     rule under every row that no background / border bucket can see. */
  #question-list .question-container,
  .question-container {
    border-color: #262c33 !important;
    box-shadow: none !important;
  }

  /* main nav (All Sites / Top 400 Users / Digests): dark navy -> accent */
  .navMain a,
  .contentWrapper .navMain a {
    color: #6fb3e8 !important;
  }

  /* sidebar module headings ("Today's Featured Site", "Top Network
     Askers") + subheader tab label: near-black #444 on dark -> light */
  #sideBar .module .heading,
  .featured-sidebar .heading,
  .users-sidebar .heading,
  .module .heading {
    color: #e6edf3 !important;
  }

  /* featured-site detail text, stat labels and the per-asker site
     names (span.sb-siteName): all near-black #444 -> muted grey */
  .featured-site .site-details,
  .featured-site .stats-label,
  .stats-label,
  .sb-siteName,
  .userDetails .sb-siteName {
    color: #9198a1 !important;
  }

  /* inactive "real-time" tab (#666) vs active "hot" tab */
  .subheader .tabs a {
    color: #9198a1 !important;
  }
  /* The active "hot" tab is brand red (text plus a 2px underline), which the blanket
     `.youarehere { border-color }` reset would flatten. */
  .subheader .tabs a.youarehere,
  .subheader .tabs a.selected {
    color: #f35d5f !important;
    border-bottom-color: #f35d5f !important;
  }

  /* legacy light frames: subheader underline (#e5e5e5), the featured-
     site card (#e8edee 2px) and the pager page-number chips (#d2d2d2) */
  .subheader,
  #mainArea .subheader {
    border-color: #262c33 !important;
  }

  #sideBar .module.featured-sidebar .featured-site,
  .featured-site {
    border-color: #2d333b !important;
  }

  /* The "Featured" tag is a <span> with an INLINE `background:#f1edfc`, unreachable
     by any class hook, and its ink comes from `.fc-purple-500` on the parent <h2> —
     the two must move together. */
  .featured-site h2 span,
  .featured-site h2 > span[style] {
    background-color: #2b2545 !important;
    background-image: none !important;
    color: #c7b3f5 !important;
  }

  /* /leagues: a cornsilk explainer aside and light row rules. The `.site-bubble`
     tiles carry each community's brand colour and are left alone. */
  .module.newuser {
    background-color: #221d14 !important;
    border-color: #3a3320 !important;
    color: #e8d4a0 !important;
  }

  .module.newuser strong,
  .module.newuser b {
    color: #f0e2bd !important;
  }

  .league-container {
    border-bottom-color: #262c33 !important;
  }

  /* Legacy pager chips paint from a white-to-grey background-IMAGE gradient over a
     transparent background-COLOR. The `.current` chip keeps SE's red brand
     gradient. */
  #question-list .page-numbers:not(.current),
  #question-list .page-sizer .page-numbers:not(.current),
  #question-list .pager .page-numbers:not(.current),
  .pager .page-numbers:not(.current),
  .page-sizer .page-numbers:not(.current) {
    background-image: none !important;
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  #question-list .page-numbers:not(.current):hover,
  .pager .page-numbers:not(.current):hover,
  .page-sizer .page-numbers:not(.current):hover {
    background-color: #222831 !important;
    color: #e6edf3 !important;
  }

  /* current page/size chip: keep the site's red pill but pin the text light */
  #question-list .page-numbers.current,
  .pager .page-numbers.current,
  .page-sizer .page-numbers.current {
    color: #ffffff !important;
  }

  /* Footer */
  #footer,
  .site-footer,
  .site-footer--copyright,
  .footerwrap {
    background-color: #0d1117 !important;
    color: #9198a1 !important;
    border-top: 1px solid #262c33 !important;
  }

  #footer a, .site-footer a { color: #8aa6bb !important; }
  #footer .site-footer--categories-item-link { color: #9198a1 !important; }
  /* `.fc-white` also sits on glyphs ON brand fills (the purple left-nav discs, the
     banner links), so scope the dimming to the footer. */
  .site-footer--nav-link,
  #footer .fc-white,
  .site-footer .fc-white {
    color: #c4cdd6 !important;
  }

  /* On the hub this bare <button> never got the Stacks `.s-btn` reset, so under our
     forced `color-scheme: dark` it falls back to the UA button (grey fill, 2px white
     border). Scoped to the consent footer id; the Q&A-site button is already
     correct. */
  #consent-footer-link button,
  #consent-footer-link .s-btn__link {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }

  /* On the Q&A sites the same control IS a `.s-btn__link`, and the link-button
     accent would invent a hierarchy SE does not draw — all four footer controls are
     one ink. */
  .site-footer button.s-btn__link,
  #footer button.s-btn__link {
    color: #8aa6bb !important;
  }

  /* Modals / popovers / dropdowns (opaque, no bleed-through) */
  .s-modal--dialog,
  .s-popover,
  .popup,
  .s-popover .s-popover--arrow,
  .js-popup,
  .topbar-dialog,
  .modal-content,
  .js-inbox-button + .topbar-dialog,
  .s-anchors.s-anchors__default {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* Stacks colours the modal's inner regions on the REGION, not the dialog, so an
     unclassed <p> inherits `--black-500`. Colour the regions themselves. */
  .s-modal--header,
  .s-modal--title {
    color: #e6edf3 !important;
  }

  .s-modal--body,
  .s-modal--subtitle,
  .s-modal--footer {
    color: #c4cdd6 !important;
  }

  /* The modal's dismiss chip keeps SE's `--black-150` (its rule out-ranks the
     `.s-btn` surface) while the text lift takes the glyph light. Darkening it also
     matches the signup modal's `.s-btn__muted` close. */
  button.s-btn.s-modal--close {
    background-color: #1c2128 !important;
  }

  button.s-btn.s-modal--close svg,
  button.s-btn.s-modal--close .svg-icon {
    color: #c4cdd6 !important;
  }

  button.s-btn.s-modal--close:hover {
    background-color: #262c33 !important;
  }

  /* The signup modal's "OR" rules are `h1::before` / `::after` borders off
     `--black-225`. Its class is a Svelte hash, so key off modal + heading; an
     `h1::before` with no `content` renders nothing, so other dialogs are
     unaffected. */
  .s-modal h1::before,
  .s-modal h1::after,
  .s-modal--dialog h1::before,
  .s-modal--dialog h1::after {
    border-color: #2d333b !important;
  }

  .s-popover::before, .s-popover::after,
  .s-popover .s-popover--arrow::before,
  .s-popover .s-popover--arrow::after {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* The TAG HOVER-CARD is NOT a `.s-popover`: a legacy `.magic-popup` whose surface
     is a plain `.-container` child on `var(--white)`, with a rotated 12px
     `.-arrow::before` carrying the same fill — the Stacks popover block above matches
     neither. Hover-mounted, on every page with a `.post-tag`; SE's `body.theme-dark`
     variant never reaches anonymous visitors. */
  .tag-popup .-container {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .tag-popup .-arrow::before {
    background: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* the top bar inbox / achievements / network dropdown panes */
  .topbar-dialog .header,
  .topbar-dialog .modal-content,
  .siteSwitcher-dialog .header {
    background-color: #20262d !important;
    color: #e6edf3 !important;
  }

  .topbar-dialog .item:hover,
  .siteSwitcher-dialog .child-site:hover {
    background-color: #222831 !important;
  }

  /* Topbar help / inbox / achievements dropdown rows carry an UNCLASSED
     `border-bottom: 1px #f1f2f3`. */
  .topbar-dialog .modal-content li,
  .topbar-dialog .modal-content ul li,
  #topbar-help-dialog .modal-content li,
  .topbar-dialog .modal-content .header,
  .siteSwitcher-dialog .modal-content li {
    border-color: #262c33 !important;
  }

  /* The help dropdown's featured footer row is unclassed, so darken every
     help-dialog li and re-elevate it with `:last-child`. */
  #topbar-help-dialog .modal-content ul li {
    background-color: transparent !important;
  }

  #topbar-help-dialog .modal-content ul li:last-child {
    background-color: #20262d !important;
  }

  /* The topbar dropdown rows' SECONDARY line (`.item-summary`) is painted from the
     raw `var(--black-500)` token, not an `.fc-black-*` utility. */
  .item-summary,
  .topbar-dialog .item-summary,
  #topbar-help-dialog .item-summary {
    color: #9198a1 !important;
  }

  /* Site-switcher community blurbs (`p.site-desc`) sit on SE's #636b74 — 2.82:1 on
     the switcher pane. */
  .site-desc,
  p.site-desc,
  .siteSwitcher-dialog .site-desc {
    color: #9198a1 !important;
  }

  /* Stacks `.s-menu` dropdowns (`.s-block-link` rows) — every network flyout.
     Driven ENTIRELY by component custom properties, so class-level colour rules never
     reach it: `--_bl-fc` (label), `--_bl-bg` (`.is-selected`, natively white),
     `--_me-divider-bg` (separator). The tokens keep the component's shape, hover
     behaviour and `__right.is-selected` accent bar. */
  .s-block-link {
    --_bl-fc: #c4cdd6 !important;
    --_bl-fc-hover: #e6edf3 !important;
    --_bl-fc-visited: #c4cdd6 !important;
  }

  .s-block-link:hover {
    --_bl-bg: #222831 !important;
  }

  .s-block-link.is-selected {
    --_bl-bg: #2d333b !important;
    --_bl-fc: #e6edf3 !important;
  }

  /* An autocomplete panel marks its ACTIVE row with the `bg-black-150` utility
     rather than `.is-selected`, so it needs a direct fill: the utility sets
     `background-color`, not `--_bl-bg`. */
  .s-block-link.bg-black-150 {
    background-color: #2d333b !important;
  }

  /* `__danger` is a SEMANTIC variant setting --_bl-fc to var(--red-400); the blanket
     !important above would flatten it. */
  .s-block-link.s-block-link__danger {
    --_bl-fc: #f85149 !important;
    --_bl-fc-hover: #ff7b72 !important;
    --_bl-fc-visited: #f85149 !important;
  }

  .s-menu {
    --_me-divider-bg: #2d333b !important;
    --_me-label-btc: #2d333b !important;
  }

  /* autocomplete / search suggestions dropdown */
  .js-search-dropdown,
  .acp-dropdown,
  .autocomplete,
  .s-popover.js-typeahead {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .acp-dropdown li:hover,
  .autocomplete li.selected {
    background-color: #222831 !important;
  }

  /* OneTrust cookie / consent banner + preference center — served to EU/anonymous
     visitors, unthemed, and built on OneTrust's own IDs/classes rather than
     Stacks. */
  #onetrust-banner-sdk,
  #onetrust-banner-sdk .ot-sdk-container,
  #onetrust-button-group-parent,
  #onetrust-pc-sdk,
  #ot-pc-content,
  #onetrust-pc-sdk .ot-pc-header,
  #onetrust-pc-sdk .ot-pc-footer,
  #onetrust-pc-sdk .ot-cat-item,
  #onetrust-pc-sdk #ot-pc-lst,
  #onetrust-pc-sdk .ot-accordion-layout {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  #onetrust-policy-title,
  #ot-pc-title,
  #onetrust-pc-sdk h2,
  #onetrust-pc-sdk h3,
  #onetrust-pc-sdk .ot-cat-header {
    color: #e6edf3 !important;
  }

  #onetrust-policy-text,
  #onetrust-banner-sdk #onetrust-policy-text span,
  #onetrust-banner-sdk .ot-b-addl-desc,
  #onetrust-banner-sdk .ot-dpd-desc,
  #onetrust-banner-sdk .ot-dpd-title,
  #onetrust-banner-sdk .ot-tcf2-vendor-count,
  #onetrust-banner-sdk #option-details-1,
  #onetrust-banner-sdk #option-details-1 li,
  #onetrust-banner-sdk ul li,
  #ot-pc-desc,
  #onetrust-pc-sdk p,
  #onetrust-pc-sdk li,
  #onetrust-pc-sdk .ot-cat-item p,
  #onetrust-pc-sdk label {
    color: #c4cdd6 !important;
  }

  #onetrust-banner-sdk a,
  #onetrust-banner-sdk .ot-link-btn,
  #onetrust-pc-sdk a,
  #onetrust-pc-sdk .ot-link-btn {
    color: #5fb0e6 !important;
  }

  /* Primary accept / reject / save buttons. SE ships these at 3-ID + type
     specificity, so mirror that exact pattern to win the cascade. */
  #onetrust-banner-sdk #onetrust-button-group button#onetrust-accept-btn-handler,
  #onetrust-banner-sdk #onetrust-button-group button#onetrust-reject-all-handler,
  #onetrust-pc-sdk #accept-recommended-btn-handler,
  #onetrust-pc-sdk .save-preference-btn-handler {
    background-color: #2f6f9f !important;
    color: #ffffff !important;
    border-color: #3b82b8 !important;
  }

  /* In the preference center the reject button carries `.ot-pc-refuse-all-handler`
     as a CLASS (no id) and SE's skin paints it `var(--black-150) !important`, so an
     id-only selector never matches. Mirror SE's 2-id selector. */
  #onetrust-banner-sdk #onetrust-button-group button#onetrust-pc-btn-handler,
  #onetrust-pc-sdk #ot-pc-refuse-all-handler,
  #onetrust-consent-sdk #onetrust-pc-sdk button.ot-pc-refuse-all-handler {
    background-color: transparent !important;
    color: #5fb0e6 !important;
    border-color: #2d333b !important;
  }

  /* "Always Active" status label: SE's skin colours it `var(--black-600)`, pure
     dark-on-dark inside the darkened panel. */
  #onetrust-pc-sdk .ot-always-active,
  #onetrust-pc-sdk .ot-cat-grp .ot-always-active,
  #onetrust-pc-sdk .ot-vs-list .ot-always-active {
    color: #8fdc9e !important;
  }

  /* Category / sub-group row dividers keep OneTrust's light greys
     (#d6d9dc, #d8d8d8, #e2e2e2) and glare as bright rules on dark. */
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-cat-item,
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-acc-hdr,
  #onetrust-consent-sdk #onetrust-pc-sdk .ot-subgrp-cntr,
  #onetrust-consent-sdk #onetrust-pc-sdk li.ot-subgrp {
