  .wmd-mini-button.selected:hover,
  .wmd-mini-button.selected {
    background-color: #3d444d !important;
    color: #e6edf3 !important;
  }

  /* ---- misc ---- */
  /* Chat's orange `.button` takes its white label from a Stacks link token the
     network-wide accent repaints to blue at 1.1:1. `#sidebar a` (1 id) out-ranks a
     bare `a.button`, so the transcript rail needs the id arms. */
  a.button,
  span.button,
  .roomcard-xxl .button,
  .frozen a.button,
