  }

  #conversation-body ul#participants li.selected {
    background-color: #3d2f1c !important;
  }

  kbd {
    background-color: #262c33 !important;
    border-color: #3d444d #2d333b #21262d #3d444d !important;
    color: #e6edf3 !important;
  }
