@-moz-document domain("api.stackexchange.com") {
.content {
    background-color: #14181d !important;
    border-top-color: #262c33 !important;
    border-bottom-color: #262c33 !important;
  }

  .module {
    color: #c4cdd6 !important;
  }

  /* Every method-index row draws its own light bottom rule; `.method-name` carries
     the same on its right edge in the two-column layout. */
  .method,
  .method-name,
  .method-description {
