  }

  .module.help {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: none !important;
  }

  /* Index rows are #6A737C and the CURRENT one `--black-800`, the least legible
     entry once the card is dark. Its orange `::before` bar already marks it. */
  .module.help a,
