  }

  .module.help ul li.list-separator {
    background: #2d333b !important;
  }

  /* `.deprecated` is a cream box framed in black, `.beta` a pink box framed in red.
     Both encode a status, so retone each to its own tinted dark, not a neutral. */
  .deprecated {
