    border-color: #4a3a1c !important;
    color: #e8c98a !important;
  }

  .beta {
    background-color: #2a1718 !important;
    border-color: #5a2a2c !important;
    color: #f0a8a8 !important;
  }

  /* The interactive console: the request-URL bar, the filter/permalink popovers
     (mounted only on click) and the filter toolbar strip. */
  .fetched-url {
