  }

  .console-header-separator:after {
    color: #3d444d !important;
  }

  /* "Run" is the only bare <button> the sheet never styles, so under the forced
     `color-scheme: dark` it falls back to the UA button. */
  button.run-button {
    background-color: #2f6f9f !important;
    border: 1px solid #3b82b8 !important;
    color: #ffffff !important;
  }

  button.run-button:hover {
    background-color: #3b82b8 !important;
  }

  /* `.manual-filter` sets `background: url(funnel--pencil.png) … white` — the
