  .manual-filter {
    background-color: transparent !important;
  }

  .manual-filter-editing {
    color: #9198a1 !important;
  }

  /* The auth flow dims the page with a 50%-opaque LIGHT grey scrim, which
     washes the whole dark page out instead of dimming it. */
  .auth-lightbox {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  #tabs a {
    color: #9198a1 !important;
  }

  /* …and the CURRENT tab, swallowed by the flat rest colour above plus the main
     block's `.youarehere { border-color }`: it is marked by a red label and a 2px
     underline of the same red. */
