    color: #f35d5f !important;
    border-bottom-color: #f35d5f !important;
  }

  #tabs a:hover {
    color: #c4cdd6 !important;
  }

  /* Below `md` the docs sidebar collapses to a `.mobile-nav` disclosure, the ONLY
