    --highlight-color: #d9e0e7 !important;
    --highlight-comment: #8b949e !important;
    --highlight-punctuation: #c4cdd6 !important;
    --highlight-namespace: #79c0ff !important;
    --highlight-attribute: #a5d6ff !important;
    --highlight-literal: #79c0ff !important;
    --highlight-symbol: #ffa657 !important;
    --highlight-keyword: #ff7b72 !important;
    --highlight-variable: #a5d6ff !important;
    --highlight-addition: #3fb950 !important;
    --highlight-deletion: #ff7b72 !important;
  }

  /* The console's date pickers are jQuery UI widgets on the stock light smoothness
     skin — a white calendar with #454545 day cells. */
  .ui-widget-content {
    background: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .ui-widget-content a,
  .ui-widget-header a {
    color: #c4cdd6 !important;
  }

  .ui-widget-header {
    background: #20262d !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  .ui-state-default,
  .ui-widget-content .ui-state-default,
  .ui-widget-header .ui-state-default {
    background: #222831 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .ui-state-hover,
  .ui-widget-content .ui-state-hover,
  .ui-widget-header .ui-state-hover {
    background: #2d333b !important;
    border-color: #3d444d !important;
    color: #e6edf3 !important;
  }

  .ui-state-highlight,
  .ui-widget-content .ui-state-highlight {
    background: #2a2114 !important;
    border-color: #4a3a1c !important;
    color: #e8c98a !important;
  }

  .ui-state-error,
  .ui-widget-content .ui-state-error {
    background: #2a1718 !important;
    border-color: #5a2a2c !important;
    color: #f0a8a8 !important;
  }

  .ui-widget-overlay {
    background: #000000 !important;
  }
}

@-moz-document domain("area51.stackexchange.com") {
/* #FBF9E2 — the page plate and everything that sits flush on it. */
