  }

  /* Area 51 loads the shared CDN `chrome.css`, whose link rule out-ranks the
     network-wide accent. Scoped to the content column so the cream-on-red notify bar,
     the cream subheader links and the white nav keep their colours; the tab rules
     below carry two classes and win. */
  .category-content a,
