  }

  .search-highlight {
    background-color: #4a3a1c !important;
    color: #f0dfae !important;
  }

  /* Footer strip: #444 links on the dark page base (1.8:1) and the
     build-stamp line under them. */
  #footer-menu,
  #footer-flair {
    color: #9198a1 !important;
  }
