@-moz-document domain("data.stackexchange.com") {
/* ---- query list ---- */
  /* The view-count tile beside every query is #fbfbfb with #999 ink. */
  .querylist .views {
    background-color: #20262d !important;
    color: #9198a1 !important;
  }

  .querylist li {
    border-bottom-color: #2d333b !important;
  }

  /* All these tabs are WHITE, the selected one distinguished only by a #ccc frame,
     so once its label is lifted the current tab is the one you cannot read. */
  #tabs a,
  .miniTabs a {
    background: #1c2128 !important;
    border-color: #2d333b !important;
    color: #9198a1 !important;
  }

  #tabs a:hover,
  .miniTabs a:hover {
    background: #222831 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  #tabs a.youarehere,
  .miniTabs a.youarehere {
    background: #222831 !important;
    border-color: #3d444d !important;
    color: #e6edf3 !important;
  }

  /* ---- query editor ---- */
  .CodeMirror {
    background: #222831 !important;
    color: #d9e0e7 !important;
  }

  .CodeMirror,
  .CodeMirror-wrapping {
    border-color: #2d333b !important;
  }

  .CodeMirror-gutters {
