  }

  .CodeMirror-guttermarker {
    color: #e6edf3 !important;
  }

  .CodeMirror-scrollbar-filler,
  .CodeMirror-gutter-filler {
    background-color: #1c2128 !important;
  }

  .CodeMirror div.CodeMirror-cursor {
    border-left-color: #e6edf3 !important;
  }

  .CodeMirror-selected {
    background: #2d333b !important;
  }

  .CodeMirror-focused .CodeMirror-selected {
    background: #2f4a63 !important;
  }

  .CodeMirror-activeline-background {
    background: #20262d !important;
  }

  .cm-s-default .error-line {
    background-color: #3a1d1f !important;
  }

  /* The SQL token palette. Grouped by meaning so the editor keeps the
     same keyword / literal / identifier distinctions it draws on white. */
  .cm-s-default span.cm-sql-keyword,
  .cm-s-default .cm-keyword {
    color: #ff7b72 !important;
  }

  .cm-s-default span.cm-sql-word,
  .cm-s-default span.cm-property,
  .cm-s-default .cm-variable-2 {
    color: #d9e0e7 !important;
  }

  .cm-s-default span.cm-sql-var,
  .cm-s-default .cm-def,
  .cm-s-default span.cm-def {
    color: #79c0ff !important;
  }

  .cm-s-default span.cm-sql-type,
  .cm-s-default span.cm-sql-function,
  .cm-s-default .cm-builtin,
  .cm-s-default .cm-variable-3,
  .cm-s-default span.cm-variable-3 {
    color: #d2a8ff !important;
  }

  .cm-s-default span.cm-sql-number,
  .cm-s-default .cm-number,
  .cm-s-default .cm-atom,
  .cm-s-default span.cm-atom {
    color: #79c0ff !important;
  }

  .cm-s-default span.cm-sql-literal,
  .cm-s-default .cm-string,
  .cm-s-default span.cm-string,
  .cm-s-default .cm-string-2,
  .cm-s-default span.cm-string-2 {
    color: #a5d6ff !important;
  }

  .cm-s-default span.cm-sql-comment,
  .cm-s-default .cm-comment {
    color: #8b949e !important;
  }

  .cm-s-default span.cm-sql-operators,
  .cm-s-default span.cm-sql-operator,
  .cm-s-default .cm-meta,
  .cm-s-default span.cm-meta,
  .cm-s-default .cm-qualifier,
  .cm-s-default span.cm-qualifier,
  .cm-s-default .cm-bracket,
  .cm-s-default span.cm-bracket {
    color: #c4cdd6 !important;
  }

  .cm-s-default span.cm-sql-special,
  .cm-s-default .cm-attribute,
  .cm-s-default span.cm-attribute,
  .cm-s-default .cm-tag,
  .cm-s-default span.cm-tag {
    color: #ffa657 !important;
  }

  .cm-s-default .cm-error,
  .cm-s-default span.cm-error,
  .cm-invalidchar {
    color: #f85149 !important;
