  div.CodeMirror span.CodeMirror-matchingbracket {
    color: #3fb950 !important;
  }

  /* Every action here is a bare `button.btn-normal` the sheet never fills, so under
     the forced `color-scheme: dark` they fall back to the UA button. Disabled is the
     same pill at 30% alpha, so the two must stay distinguishable. */
  button.btn-normal {
    background-color: #2f6f9f !important;
