  }

  /* The editor toolbar's group divider (#ccc) and the rail's collapse
     toggle, which keeps the raw #0077cc at 3.8:1 on the page base. */
  span.button-group {
    border-left-color: #2d333b !important;
  }

  #schema-toggle,
  li#schema-toggle {
    color: #5fb0e6 !important;
  }

  /* ---- schema browser + revision history rails ---- */
  /* Both rails are `#query .right-group`, painted #fdfdfd under a
     repeating `diagonal.png` hatch that survives any bg-colour reset. */
  #query .right-group,
  #schema.right-group,
  #history.right-group {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #2d333b !important;
  }

  #schema .heading,
  #history .heading {
    background-color: #20262d !important;
    border-bottom-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  #schema .schema-table,
  #schema .table-data-panel .schema-table,
  #schema .table-data-panel th {
    background-color: #20262d !important;
    border-bottom-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* The expanded table's column list: a white `dd` carrying the type in
     #800080, which is 1.6:1 the moment the panel goes dark. */
  #schema dl dd {
    background-color: #1c2128 !important;
    border-bottom-color: #262c33 !important;
    color: #d2a8ff !important;
  }

  #schema dl dt {
    border-right-color: #2d333b !important;
  }

  /* The column panel slides over the table list on a 95%-opaque WHITE
     backdrop — it must stay opaque, so darken it rather than clear it. */
  #schema .table-data-panel {
    background-color: rgba(28, 33, 40, 0.97) !important;
  }

  #schema .table-data-panel td {
    border-bottom-color: #262c33 !important;
    border-left-color: #262c33 !important;
  }

  #history li {
    background: #1c2128 !important;
    border-bottom-color: #2d333b !important;
  }

  #history li.selected {
    background-color: #2a2417 !important;
  }

  #history li.empty {
    color: #9198a1 !important;
  }

  #history li a.user {
    color: #9198a1 !important;
  }

  /* The drag handle under each rail is a light sprite tile on #eee. */
  div.grippie {
    background-color: #20262d !important;
    border-color: #2d333b !important;
  }

  /* ---- results, messages, dialogs ---- */
  #query-results .panel {
    border-color: #2d333b !important;
  }

  #query-results .download-button:hover {
    background-color: #222831 !important;
  }

  #messages {
    background-color: #20262d !important;
  }

  #queryBodyText,
  .mainbar pre {
    background-color: #222831 !important;
    border-color: #2d333b !important;
  }

  .error-message {
    background-color: #2a1718 !important;
    border-color: #5a2a2c !important;
    color: #f0a8a8 !important;
  }

  .error-message.notice {
    background-color: #16221a !important;
    border-color: #25402d !important;
    color: #8fdc9e !important;
  }

  .input-validation-error {
    background-color: #2a1718 !important;
    border-color: #a03a40 !important;
  }

  /* Save / login dialogs: a white panel inside a 5px grey frame. */
  .dialog {
    background-color: #1c2128 !important;
    border-color: #3d444d !important;
    color: #c4cdd6 !important;
  }

  .graph-tooltip {
    background-color: #2a1718 !important;
    border-color: #5a2a2c !important;
    color: #f0a8a8 !important;
  }

  /* ---- shared chrome ---- */
  blockquote,
  #user-about-me,
  .tabular-list dt,
  table.example-set th {
    background-color: #222831 !important;
    color: #c4cdd6 !important;
  }

  table.example-set,
  table.example-set th,
  table.example-set td,
  fieldset {
    border-color: #2d333b !important;
  }

  .date_brick {
    background-color: #20262d !important;
    color: #9198a1 !important;
  }

  /* The per-site blurb in the right rail and the site-list counts: #666 and
     a raw --blue-500 #0c57a0, both around 3:1 on the page base. */
  p.tagline,
  .site-list li .stats li .desc,
  .site-list li .stats li.link a,
  .site-list li .stats li.link a:visited,
  .info-wrapper .info,
  .no-overflow {
    color: #9198a1 !important;
  }

  .pretty-short,
  span.pretty-short {
    color: #7cc0ea !important;
  }

  .user-info.owner {
    background-color: #16202c !important;
  }

  .user-info .relativetime {
    color: #9198a1 !important;
  }

  input,
  select,
  button,
  textarea {
    border-color: #2d333b !important;
  }

  /* The site-switcher popup in the nav and the query-name autocomplete
     share one `.ac_results` list: #f6f6f6 panels with a #d9e6f3 hover. */
  .ac_results,
  nav.primary .site-selector-popup {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .ac_odd.ac_over,
  .ac_even.ac_over,
  nav.primary .site-selector-popup .ac_results li.ac_over {
    background-color: #222831 !important;
    border-color: #3d444d !important;
  }

  nav.primary .nav .site-selector-arrow .site-icon-wrapper {
    background-color: #2d333b !important;
  }

  /* These are `nav.primary .nav li` on a flat #777 with white labels. The
     selected/hover arm is a separate #0c57a0 rule that already reads on dark, so
     retone only the rest state and repeat the `.youarehere` / `a:hover` arms after
     it. */
  nav.primary .nav li {
    background-color: #20262d !important;
  }

  nav.primary .nav .youarehere,
  nav.primary .nav li:hover,
  nav.primary .nav .site-selector-arrow.youarehere,
  nav.primary .nav .site-selector-arrow:hover {
    background-color: #0c57a0 !important;
  }

  nav.primary .nav li.site-selector-arrow {
    border-left-color: #3d444d !important;
  }

  .page-numbers {
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .page-numbers.current,
  span.page-numbers.current {
    background-color: #3d444d !important;
    border-color: #3d444d !important;
    color: #ffffff !important;
  }

  /* User-list card metadata (#777 on the page base). */
  .user-saved-queries,
  .user-created {
    color: #9198a1 !important;
  }

  .search-highlight {
    background-color: #4a3a1c !important;
    color: #f0dfae !important;
  }

  /* Legacy Data Explorer markup, not the Stacks OAuth pills. The provider glyph is a
     sprite and stays untouched. `.custom-login` is the same widget's icon/label
     split, rendering no node for anonymous visitors here. */
  .preferred-login,
  .preferred-login.custom-login {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: none !important;
    color: #c4cdd6 !important;
  }

  .preferred-login.custom-login .icon-container {
    background-color: #1c2128 !important;
    border-right-color: #2d333b !important;
  }

  .preferred-login.custom-login .text {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }
}
